import{b as e,O as t,g as l,j as c}from"./chunks/framework.DcaUmd3X.js";const i=JSON.parse('{"title":"羊皮卷","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/scroll-marked/index.md","filePath":"读书感悟/电子书架/11.羊皮卷.md","lastUpdated":1781614933000}'),p={name:"reading/digital/scroll-marked/index.md"};function u(a,o,b,k,q,r){return t(),l("div",null,[...o[0]||(o[0]=[c('<h1 id="羊皮卷" tabindex="-1">羊皮卷 <a class="header-anchor" href="#羊皮卷" aria-label="Permalink to &quot;羊皮卷&quot;">​</a></h1><p><code>卡耐基</code> <code>励志成长</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 人们在生活之中总是会被各种各样的“小问题”所干扰，这些小问题会影响我们的判断，影响我们的情绪，影响我们的生活</p></blockquote><blockquote><p>📌 我们面对问题的时候该做的，或者能做的不过是判断，进而选择。要么去愁眉苦脸地承受生活带给我们的无穷无尽的烦恼，要么积极主动地去享受生活赐予我们的无限的选择权！</p></blockquote><blockquote><p>📌 请不要为生活带给我们如此多的烦恼而抱怨，上帝是公平的，他在给我们烦恼的同时，也早已为我们提供了解决烦恼的钥匙</p></blockquote><blockquote><p>📌 人们常说要想了解一个人的思想，只要去观察他看什么书就可以了；要想了解一个人的情绪，只要看他听什么音乐就可以了；而要想了解他是谁，只要看他身边有什么样的朋友就可以了！</p></blockquote><blockquote><p>📌 为了我们的梦想，应该尽量选择那些适合自己的，对自己的成长有所帮助的环境，不然就很难寻找到我们所希望的幸福。</p></blockquote><blockquote><p>📌 那就是任何人的尊严都是上帝赐予的礼物，没有任何人、法律或者政令与权威有权利夺走这种天赋的神圣权利。</p></blockquote><blockquote><p>📌 我必须告诉那些站在通往正义之宫的温暖入口处的人们，我们在争取合法地位的进程中，绝不能轻举妄动，采取错误的做法。</p></blockquote><blockquote><p>📌 身是菩提树，心如明镜台。殷殷勤拂拭，不教惹尘埃。”</p></blockquote><blockquote><p>📌 菩提本非树，明镜亦非台。本来无一物，何处惹尘埃。”</p></blockquote><blockquote><p>📌 只要你不去为它们分心，就完全可以当它们并不存在</p></blockquote><blockquote><p>📌 可见，这世上真的很少有“不可能被克服”的困难，许多我们认为“不可能”的事情与“聋子音乐家”相比实在是再平常不过的小问题！</p></blockquote><blockquote><p>📌 坚持理想，不断思索！</p></blockquote><blockquote><p>📌 我行的！我的生活本就可以更美好”</p></blockquote><blockquote><p>📌 每个人迈向成功的第一个步骤，也是不能漏掉的基本步骤，就是要相信自己，要相信自己一定能够成功</p></blockquote><blockquote><p>📌 你比你想象的还要好。成功的人并不是超人。成功不需要超人的智力，不是看运气，也没有什么神秘之处。成功的人只是相信自己、肯定自己所作所为的平凡人。永远不要，绝对不要廉价出售自己。</p></blockquote><blockquote><p>📌 我们应该坚信我们所做的事情是有意义的，只有这样，才能不断地保持激情，激励着自己永不疲倦地奔向梦想的方向。</p></blockquote><blockquote><p>📌 我们要做的第一步是放慢自己的生活节奏。</p></blockquote><blockquote><p>📌 我的第二条建议是保持节奏，保持好自己生活的节奏，这种让自己可以长期稳定的节奏比一段又一段冲刺，却因此而陷入混乱更容易带领我们实现理想，达到目标。</p></blockquote><blockquote><p>📌 所以当我们因为一些无谓的事情而忧虑的时候，可以想一些开心的事情，或者更多地思考只要我们努力办好眼前的事情，就会得到怎样的快乐与幸福感。</p></blockquote><blockquote><p>📌 上山缚虎易，开口告人难”</p></blockquote><blockquote><p>📌 这世上没有陌生人，只有我们还未曾认识的朋友。”</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 努力</p><p>📌 当我们毫不松懈地朝着目标努力的时候，相信我，我们的理想就在前方不远之处。</p></blockquote><blockquote><p>💭 人民有信仰，国家才有希望</p><p>📌 智慧、力量与成就，世间所能拥有的一切，一切能帮助我们获得美好生活的财富所共同拥有的前提就是信仰！</p></blockquote><blockquote><p>💭 认定一件事情就努力去完成它，这一路上会遇到挫折，但这些只不过是你成功路上的考验</p><p>📌 在通往梦想的道路之上，巴尔扎克，或者一切的天才如此不可战胜，正是因为他们掌握了“凝念”的能力与方法。</p></blockquote><blockquote><p>💭 多尝试</p><p>📌 洛克菲勒的人生格言：“凡事都得试试，哪怕希望微乎其微。”</p></blockquote>',29)])])}const n=e(p,[["render",u]]);export{i as __pageData,n as default};
